query getWhatsChanged($startTsSec: Long!, $endTsSec: Long!, $filter: Filter) {
  whatsChanged(
    startTsSec: $startTsSec
    endTsSec: $endTsSec
    filter: $filter
  ) {
    fromRootScore {
      date
      score
    }
    toRootScore {
      date
      score
    }
    keyVariations {
      parentId
      parentName
      parentUuid
      metricLevel
      id
      name
      impact
      parentAppType
      diagnoseUrl
      devicesInvestigationUrl
      usersInvestigationUrl
      impactInsights
    }
  }
}
